; ==================================================================
; SPRITE INITIALIZATION FUNCTIONS
; ==================================================================

INIT_SPRITES:
    ; Initialize sprite system
    CALL CLEAR_ALL_SPRITES

    ; Load sprite patterns to VRAM
    CALL LOAD_SPRITE_PATTERNS

    ; Initialize sprite positions (all invisible by default)
    XOR A
    LD (active_sprite_count), A

    RET

LOAD_SPRITE_PATTERNS:
    ; Load all sprite patterns to VRAM sprite pattern table

    ; Load sprite 0 frame 0: bot1 (BIOS LDIRVM handles timing)
    LD HL, BOT1_F0_LAYER3
    LD DE, SPRPAT + (0 * 32) ; Each 16x16 sprite = 32 bytes
    LD BC, 32                       ; 16x16 sprite size
    CALL LDIRVM                     ; BIOS handles safe VRAM access

    ; Load frame 1
    LD HL, BOT1_F1_LAYER3
    LD DE, SPRPAT + (4 * 8) ; 32 bytes ahead (pattern 4 effective address)
    LD BC, 32
    CALL LDIRVM

    RET

; ==================================================================
; SPRITE MANAGEMENT FUNCTIONS
; ==================================================================

; Show sprite (A = sprite number, B = X, C = Y, D = pattern, E = color)
SHOW_SPRITE:
    ; Input: A=sprite#, B=X, C=Y, D=pattern, E=color
    PUSH BC
    PUSH DE

    LD L, A                      ; L = sprite number
    LD H, 0                      ; HL = sprite number
    SLA L
    RL H                         ; *2
    SLA L
    RL H                         ; *4 (for interleaved offset)
    LD DE, sprite_attr
    ADD HL, DE                   ; HL = sprite_attr + (sprite# * 4)

    LD (HL), C                   ; Set Y
    INC HL
    LD (HL), B                   ; Set X
    INC HL
    LD (HL), D                   ; Set pattern
    INC HL
    LD (HL), E                   ; Set color

    POP DE
    POP BC
    RET

; Clear all sprites (make them invisible)
CLEAR_ALL_SPRITES:
    LD HL, sprite_attr
    LD DE, sprite_attr+1
    LD BC, 127                     ; 128 bytes - 1
    LD (HL), SPRITE_INVISIBLE     ; Y=209 (invisible) for first, then LDIR fills rest
    LDIR
    RET

; Hide specific sprite (A = sprite number)
HIDE_SPRITE:
    LD L, A
    LD H, 0
    SLA L
    RL H
    SLA L
    RL H
    LD DE, sprite_attr
    ADD HL, DE
    LD (HL), SPRITE_INVISIBLE     ; Set Y invisible
    RET

; Update sprite positions to VRAM
UPDATE_SPRITES_TO_VRAM:
    ; Copy sprite attributes from RAM to VRAM
    ; BIOS LDIRVM handles timing automatically
    LD HL, sprite_attr
    LD DE, SPRATR
    LD BC, 128                    ; 32 sprites * 4 bytes each
    CALL LDIRVM                   ; BIOS handles safe VRAM access
    RET

