; ==================================================================
; GAME COMPONENTS
; ==================================================================

; ==================================================================
; DEFAULT COMPONENT SYSTEM
; ==================================================================

; Basic component types
COMP_POSITION   EQU 0
COMP_SPRITE     EQU 1
COMP_MOVEMENT   EQU 2
COMP_COLLISION  EQU 3

INIT_COMPONENTS:
    ; Initialize basic component system
    RET

UPDATE_POSITION_COMPONENT:
    ; Update position components
    RET

UPDATE_SPRITE_COMPONENT:
    ; Update sprite components
    ; Basic animation for bot1
    LD HL, frame_counter
    INC (HL)
    LD A, (HL)
    AND #08  ; Flip every 8 frames
    LD D, 0
    JR Z, .no_flip
    LD D, 4  ; Pattern 4 for frame 1
.no_flip:
    LD HL, sprite_attr + (0 * 4) + 2  ; Pattern offset for sprite 0
    LD (HL), D
    RET

UPDATE_MOVEMENT_COMPONENT:
    ; Update movement components
    ; Basic enemy movement: move left/right
    LD HL, frame_counter
    LD A, (HL)
    BIT 4, A  ; Change direction every 16 frames
    JR Z, .move_right
    LD HL, sprite_attr + (0 * 4) + 1  ; X offset for sprite 0
    DEC (HL)  ; Move left
    RET
.move_right:
    LD HL, sprite_attr + (0 * 4) + 1  ; X offset
    INC (HL)  ; Move right
    RET

UPDATE_COLLISION_COMPONENT:
    ; Update collision components
    RET

UPDATE_INPUT_COMPONENT:
    ; Update input handling
    LD A, 0                    ; Joystick port 0
    CALL GTSTCK                ; Get joystick status
    LD (input_state), A        ; Store current input state
    RET

; ==================================================================
; VDP CONFIGURATION AND SYNCHRONIZATION FUNCTIONS
; ==================================================================

; Note: Using only CHGMOD is sufficient - BIOS handles all VDP configuration automatically

; ==================================================================
; END OF COMPONENTS
; ==================================================================


