; Basic entity structure
ENTITY_PLAYER_ID EQU 0
ENTITY_ENEMY_ID  EQU 1

INIT_ENTITIES:
    ; Initialize default entities
    CALL INIT_PLAYER
    ; Show test sprite (bot1 as basic enemy)
    LD A, SPRITE_ID_BOT1      ; Sprite 0
    LD B, 100                 ; X = 100
    LD C, 80                  ; Y = 80
    LD D, 0                   ; Pattern 0
    LD E, 15                  ; Color 15 (white)
    CALL SHOW_SPRITE
    LD A, 1
    LD (active_sprite_count), A
    RET

UPDATE_ENTITIES:
    ; Update all entities
    CALL UPDATE_PLAYER
    RET

INIT_PLAYER:
    ; Initialize player entity
    RET

UPDATE_PLAYER:
    ; Update player logic
    RET

