; ==================================================================
; GAME MENUS
; ==================================================================

; ==================================================================
; DEFAULT MENU SYSTEM
; ==================================================================

; Menu constants
MENU_MAIN_ID     EQU 0
MENU_GAME_ID     EQU 1
MENU_PAUSE_ID    EQU 2

; Menu items
MENU_ITEM_START  EQU 0
MENU_ITEM_EXIT   EQU 1

; Current menu variables
current_menu     DS 1
current_item     DS 1

; ==================================================================
; MENU FUNCTIONS
; ==================================================================

INIT_MENUS:
    ; Initialize menu system
    LD A, MENU_MAIN_ID
    LD (current_menu), A
    XOR A
    LD (current_item), A
    RET

SHOW_MAIN_MENU:
    ; Display main menu
    CALL CLS

    ; Print title
    LD HL, txt_title
    LD DE, NAMETBL + (5 * 32) + 10  ; Row 5, column 10
    CALL PRINT_STRING

    ; Print menu options
    LD HL, txt_start
    LD DE, NAMETBL + (10 * 32) + 12
    CALL PRINT_STRING

    LD HL, txt_exit
    LD DE, NAMETBL + (12 * 32) + 12
    CALL PRINT_STRING

    RET

HANDLE_MAIN_MENU:
    ; Handle main menu input
    LD A, (input_state)  ; Use pre-fetched input

    ; Check for up/down movement
    CP STICK_UP            ; Up
    JP Z, menu_up
    CP STICK_DOWN            ; Down
    JP Z, menu_down

    ; Check for selection (fire button)
    LD A, 0
    CALL GTTRIG
    OR A
    JP NZ, menu_select

    RET

menu_up:
    LD A, (current_item)
    OR A
    JP Z, menu_up_end  ; Already at top
    DEC A
    LD (current_item), A
menu_up_end:
    RET

menu_down:
    LD A, (current_item)
    CP MENU_ITEM_EXIT
    JP Z, menu_down_end  ; Already at bottom
    INC A
    LD (current_item), A
menu_down_end:
    RET

menu_select:
    LD A, (current_item)
    CP MENU_ITEM_START
    JP Z, start_game
    CP MENU_ITEM_EXIT
    JP Z, exit_game
    RET

start_game:
    ; Start the game
    LD A, FLOW_STATE_GAME
    LD (current_flow_state), A
    RET

exit_game:
    ; Exit to BASIC
    RST #00

; ==================================================================
; MENU TEXT DATA
; ==================================================================

txt_title:
    DB "GAME TITLE", 0

txt_start:
    DB "START GAME", 0

txt_exit:
    DB "EXIT", 0

; ==================================================================
; TEXT PRINTING FUNCTION
; ==================================================================

PRINT_STRING:
    ; Print null-terminated string
    ; HL = source string, DE = VRAM destination
print_loop:
    LD A, (HL)
    OR A
    RET Z           ; End of string

    ; WRTVRM expects: A = data, HL = VRAM address
    PUSH HL         ; Save string pointer
    PUSH DE         ; Save VRAM address
    POP HL          ; HL = VRAM address (for WRTVRM)
    CALL WRTVRM     ; Write character to VRAM
    POP HL          ; Restore string pointer

    INC HL          ; Next character in string
    INC DE          ; Next VRAM position
    JP print_loop

; ==================================================================
; END OF MENUS
; ==================================================================


; ==================================================================
; MAIN PROGRAM (from main.asm - excluding includes)
; ==================================================================
MAIN_PROGRAM:
    ; Initialize game systems
    CALL INIT_GAME_SYSTEMS

    ; Initialize Game Flow system
    XOR A
    LD (current_flow_state), A
    LD (prev_flow_state), A

    ; Start with main menu
    LD A, FLOW_STATE_MAIN_MENU
    LD (current_flow_state), A

    ; Main loop
MAIN_LOOP:
    HALT                 ; Wait for V-Blank
    CALL UPDATE_CURRENT_STATE
    CALL RENDER_FRAME
    JP MAIN_LOOP

; ==================================================================
; GAME SYSTEM FUNCTIONS (implemented)
; ==================================================================

INIT_GAME_SYSTEMS:
    ; Initialize MSX hardware and game systems
    LD A, SCREEN2
    CALL CHGMOD               ; Set Screen 2 mode (BIOS handles everything)

    ; Set VDP reg 1 for 16x16 sprites (non-magnified)
    LD BC, #01E2              ; Reg 1: E2 (size=1, mag=0)
    CALL WRTVDP

    CALL ERAFNK               ; Remove function keys

    ; Initialize component systems
    CALL INIT_COMPONENTS

    ; Initialize sprite system if available
    CALL INIT_SPRITES

    ; Load tile patterns and colors
    CALL LOAD_PATTERN_BANK0
    CALL LOAD_PATTERN_BANK1
    CALL LOAD_PATTERN_BANK2
    CALL LOAD_COLOR_BANK0
    CALL LOAD_COLOR_BANK1
    CALL LOAD_COLOR_BANK2

    ; Load character patterns and colors for text
    CALL LOAD_CHARACTER_PATTERNS
    CALL LOAD_CHARACTER_COLORS

    ; Initialize entities (shows sprite)
    CALL INIT_ENTITIES

    ; Initialize menus
    CALL INIT_MENUS

    ; Initialize sound system
    CALL GICINI               ; Initialize PSG

    ; Clear screen (BIOS CLS handles timing)
    CALL CLS

    ; Show initial startup message
    LD DE, NAMETBL + (1 * 32) + 1  ; Row 1, col 1
    LD HL, txt_system_init
    CALL PRINT_STRING

    RET

LOAD_CHARACTER_PATTERNS:
    ; Copy character patterns from BIOS ROM to VRAM (tiles 32-255)
    LD HL, (#F91F)            ; CGPNT system var
    LD DE, CHRTBL2 + (32 * 8) ; Start at tile 32
    LD BC, 224 * 8            ; 224 tiles * 8 bytes
    CALL LDIRVM

    ; Bank 1
    LD HL, (#F91F)
    LD DE, CHRTBL2 + #800 + (32 * 8)
    LD BC, 224 * 8
    CALL LDIRVM

    ; Bank 2
    LD HL, (#F91F)
    LD DE, CHRTBL2 + #1000 + (32 * 8)
    LD BC, 224 * 8
    CALL LDIRVM
    RET

LOAD_CHARACTER_COLORS:
    ; Fill character colors (white on black) for tiles 32-255
    LD HL, CLRTBL2 + (32 * 8) ; Start at tile 32
    LD BC, 224 * 8            ; 224 tiles * 8 bytes
    LD A, #F1                 ; White fg, black bg
    CALL FILVRM

    ; Bank 1
    LD HL, CLRTBL2 + #800 + (32 * 8)
    LD BC, 224 * 8
    LD A, #F1
    CALL FILVRM

    ; Bank 2
    LD HL, CLRTBL2 + #1000 + (32 * 8)
    LD BC, 224 * 8
    LD A, #F1
    CALL FILVRM
    RET

UPDATE_CURRENT_STATE:
    ; Update game logic based on current flow state
    LD A, (current_flow_state)
    CP FLOW_STATE_MAIN_MENU
    JP Z, UPDATE_MAIN_MENU_STATE
    CP FLOW_STATE_GAME
    JP Z, UPDATE_GAME_STATE
    CP FLOW_STATE_PAUSE
    JP Z, UPDATE_PAUSE_STATE
    CP FLOW_STATE_GAME_OVER
    JP Z, UPDATE_GAME_OVER_STATE
    CP FLOW_STATE_CREDITS
    JP Z, UPDATE_CREDITS_STATE
    RET

UPDATE_MAIN_MENU_STATE:
    ; Handle main menu input and logic
    CALL UPDATE_INPUT_COMPONENT
    CALL HANDLE_MAIN_MENU
    RET

UPDATE_GAME_STATE:
    ; Main gameplay logic - update all component systems
    CALL UPDATE_INPUT_COMPONENT
    CALL UPDATE_POSITION_COMPONENT
    CALL UPDATE_MOVEMENT_COMPONENT
    CALL UPDATE_COLLISION_COMPONENT
    CALL UPDATE_SPRITE_COMPONENT
    CALL UPDATE_ENTITIES
    RET

UPDATE_PAUSE_STATE:
    ; Handle pause state
    CALL UPDATE_INPUT_COMPONENT

    ; Check for unpause input
    RET

UPDATE_GAME_OVER_STATE:
    ; Handle game over state
    CALL UPDATE_INPUT_COMPONENT

    ; Check for restart/menu input
    RET

UPDATE_CREDITS_STATE:
    ; Handle credits state
    ; Auto-advance credits or return to menu
    RET

RENDER_FRAME:
    ; Render current frame based on flow state
    ; Debug: Show frame indicator
    LD HL, NAMETBL + (23 * 32) + 30
    LD A, '*'
    CALL WRTVRM

    ; Check current flow state and render appropriately
    LD A, (current_flow_state)
    CP FLOW_STATE_MAIN_MENU
    JP Z, RENDER_MAIN_MENU
    CP FLOW_STATE_GAME
    JP Z, RENDER_GAME
    CP FLOW_STATE_PAUSE
    JP Z, RENDER_PAUSE
    CP FLOW_STATE_GAME_OVER
    JP Z, RENDER_GAME_OVER
    CP FLOW_STATE_CREDITS
    JP Z, RENDER_CREDITS

    ; Default: show unknown state debug info
    LD DE, NAMETBL + (2 * 32) + 1
    LD HL, txt_debug_state
    CALL PRINT_STRING
    RET

RENDER_MAIN_MENU:
    ; Render main menu interface
    CALL CLS                   ; Clear screen first

    ; Position for title
    LD DE, NAMETBL + (8 * 32) + 10
    LD HL, txt_main_title
    CALL PRINT_STRING

    ; Position for menu option 1
    LD DE, NAMETBL + (12 * 32) + 12
    LD HL, txt_start_game
    CALL PRINT_STRING

    ; Position for menu option 2
    LD DE, NAMETBL + (14 * 32) + 12
    LD HL, txt_exit_game
    CALL PRINT_STRING
    RET

RENDER_GAME:
    ; Render game frame - load actual screen map
    ; BIOS LDIRVM in screen loading handles timing automatically
    CALL LOAD_SCREEN_PANTALLA1

    ; Display game status at top
    LD DE, NAMETBL + (1 * 32) + 1
    LD HL, txt_game_mode
    CALL PRINT_STRING

    ; Update sprites
    CALL UPDATE_SPRITES_TO_VRAM
    RET

RENDER_PAUSE:
    ; Render pause overlay
    ; Position in center
    LD DE, NAMETBL + (12 * 32) + 14
    LD HL, txt_paused
    CALL PRINT_STRING
    RET

RENDER_GAME_OVER:
    ; Render game over screen
    CALL CLS                   ; Clear screen

    ; Position for game over message
    LD DE, NAMETBL + (10 * 32) + 12
    LD HL, txt_game_over
    CALL PRINT_STRING

    ; Position for instruction
    LD DE, NAMETBL + (14 * 32) + 8
    LD HL, txt_press_any_key
    CALL PRINT_STRING
    RET

RENDER_CREDITS:
    ; Render credits screen
    CALL CLS                   ; Clear screen

    ; Position for credits
    LD DE, NAMETBL + (8 * 32) + 8
    LD HL, txt_credits
    CALL PRINT_STRING
    RET

; Text strings for display
txt_system_init:    DB "MSX SYSTEM READY", 0
txt_debug_state:    DB "UNKNOWN STATE", 0
txt_main_title:     DB "MSX GAME ENGINE", 0
txt_start_game:     DB "1. START GAME", 0
txt_exit_game:      DB "2. EXIT", 0
txt_game_mode:      DB "GAME MODE", 0
txt_paused:         DB "PAUSED", 0
txt_game_over:      DB "GAME OVER", 0
txt_press_any_key:  DB "PRESS ANY KEY", 0
txt_credits:        DB "CREDITS: MIDEAS MSX", 0

    END                 ; End of assembl